def safe_cell(row, idx, default=''):
    return row[idx] if isinstance(row, list) and idx < len(row) else default

def build_map(values, key_idx, take_idxs):
    out={}
    for r in (values[1:] if values else []):
        k=str(safe_cell(r,key_idx,'')).strip()
        if k:
            out[k]=[safe_cell(r,i,'') for i in take_idxs]
    return out

def join(target_values, m, key_idx, header, empty_cols):
    rows=[header]
    for r in (target_values[1:] if target_values else []):
        k=str(safe_cell(r,key_idx,'')).strip()
        rows.append(m.get(k) or list(empty_cols))
    return rows
